import type { OauthGrant, OauthGrantCreate, OauthGrantUpdate } from './model';
import { OauthGrantRepository, OauthGrantNotFoundError } from './repository';
import { validateOauthGrantCreate, validateOauthGrantUpdate } from './validator';

export interface OauthGrantServiceDeps {
  repository: OauthGrantRepository;
  clock?: () => Date;
  logger?: (msg: string, meta?: Record<string, unknown>) => void;
}

export interface ListOauthGrantOptions {
  offset?: number;
  limit?: number;
  sortBy?: keyof OauthGrant;
  order?: 'asc' | 'desc';
}

/**
 * Business-logic layer above OauthGrantRepository.
 */
export class OauthGrantService {
  private readonly repo: OauthGrantRepository;
  private readonly clock: () => Date;
  private readonly logger: (msg: string, meta?: Record<string, unknown>) => void;

  constructor(deps: OauthGrantServiceDeps) {
    this.repo = deps.repository;
    this.clock = deps.clock ?? (() => new Date());
    this.logger = deps.logger ?? (() => { /* noop */ });
  }

  create(input: OauthGrantCreate): OauthGrant {
    const errors = validateOauthGrantCreate(input);
    if (errors.length > 0) throw new OauthGrantValidationError(errors);
    const created = this.repo.insert(input);
    this.logger('OauthGrantService.create', { id: created.id });
    return created;
  }

  get(id: string): OauthGrant {
    return this.repo.requireById(id);
  }

  tryGet(id: string): OauthGrant | undefined {
    return this.repo.findById(id);
  }

  update(id: string, patch: OauthGrantUpdate): OauthGrant {
    const errors = validateOauthGrantUpdate(patch);
    if (errors.length > 0) throw new OauthGrantValidationError(errors);
    const updated = this.repo.update(id, patch);
    this.logger('OauthGrantService.update', { id });
    return updated;
  }

  delete(id: string): void {
    const existed = this.repo.delete(id);
    if (!existed) throw new OauthGrantNotFoundError(id);
    this.logger('OauthGrantService.delete', { id });
  }

  list(options: ListOauthGrantOptions = {}): OauthGrant[] {
    const offset = options.offset ?? 0;
    const limit = options.limit ?? 50;
    if (options.sortBy) {
      const sorted = this.repo.sortedBy(options.sortBy, options.order);
      return sorted.slice(offset, offset + limit);
    }
    return this.repo.paginate(offset, limit);
  }

  countAll(): number {
    return this.repo.count();
  }

  batchCreate(inputs: OauthGrantCreate[]): OauthGrant[] {
    for (const input of inputs) {
      const errors = validateOauthGrantCreate(input);
      if (errors.length > 0) throw new OauthGrantValidationError(errors);
    }
    return this.repo.batchInsert(inputs);
  }

  exists(id: string): boolean {
    return this.repo.findById(id) !== undefined;
  }

  bulkDelete(ids: string[]): number {
    let deleted = 0;
    for (const id of ids) if (this.repo.delete(id)) deleted++;
    return deleted;
  }

  searchByField<K extends keyof OauthGrant>(field: K, value: OauthGrant[K]): OauthGrant[] {
    return this.repo.filter((entity) => entity[field] === value);
  }
}

